@using sv_4c89d324cc814d3faeaf36f2907b01ba.Components.Application
@using sv_4c89d324cc814d3faeaf36f2907b01ba.Models

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="mt-3">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Model="_personalInfo"
                                  OnNext="NextStep" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;

            case 2:
                <ReferencesStep References="_references"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 CoverLetterChanged="val => _coverLetter = val"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;

            case 4:
                <ReviewStep Personal="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            OnSubmit="() => { }" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();

    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private readonly List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
    private string _coverLetter = "";

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        if (_currentStep < 4)
            _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
            _currentStep = step;
    }
}

using sv_4c89d324cc814d3faeaf36f2907b01ba.Models;

namespace sv_4c89d324cc814d3faeaf36f2907b01ba.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500);
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500);
        return !string.IsNullOrWhiteSpace(email) && email.Contains('@') && email.Contains('.');
    }
}

@namespace sv_4c89d324cc814d3faeaf36f2907b01ba.Components.Application

<nav aria-label="Application progress" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var isCurrent = stepIndex == CurrentStep;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isFuture = !isCurrent && !isCompleted;

            <div class="text-center flex-fill" style="z-index: 1;">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepButtonClass(isCurrent, isCompleted, isFuture)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture)"
                        @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                    @StepNames[stepIndex]
                </div>
            </div>
        }
    </div>
</nav>

