@namespace sv_4c89d324cc814d3faeaf36f2907b01ba.Components.Application

<nav aria-label="Application progress" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var isCurrent = stepIndex == CurrentStep;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isFuture = !isCurrent && !isCompleted;

            <div class="text-center flex-fill" style="z-index: 1;">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepButtonClass(isCurrent, isCompleted, isFuture)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture)"
                        @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                    @StepNames[stepIndex]
                </div>
            </div>
        }
    </div>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static string StepButtonClass(bool isCurrent, bool isCompleted, bool isFuture)
    {
        if (isCurrent) return "btn-primary";
        if (isCompleted) return "btn-success";
        return "btn-outline-secondary";
    }
}

